  "q": "어느 회사는 AWS CloudFormation 템플릿으로 새 Amazon EC2 인스턴스를 시작하고, AWS OpsWorks로 필요한 소프트웨어를 설치·구성한 뒤 각 EC2 인스턴스의 이미지를 만들어 사용자 지정 AMI 이미지를 생성합니다. 소프트웨어 설치·구성 과정은 2~3시간이 걸리지만 설치 오류로 멈춰버리는 경우가 있습니다. CloudOps 엔지니어는 과정이 멈추면 스택 전체가 실패하고 롤백되도록 CloudFormation 템플릿을 수정해야 합니다. 이 요구 사항에 따라 템플릿에 무엇을 추가해야 합니까?",
