 "soapt-q032": {
  "q": "어느 회사가 최근 애플리케이션을 AWS의 `VPC`로 마이그레이션했습니다. AWS Site-to-Site `VPN` 연결이 회사 온프레미스 네트워크와 그 `VPC`를 연결합니다. 이 애플리케이션은 온프레미스에 있는 다른 시스템에서 고객 데이터를 가져오며, 도메인 레코드 확인에는 온프레미스 `DNS` 서버를 사용합니다. 마이그레이션 후 이름 확인 오류 때문에 애플리케이션이 고객 데이터에 연결할 수 없습니다. 애플리케이션이 내부 도메인 이름을 확인할 수 있게 하는 솔루션은 무엇입니까?",
  "c": [
   "`VPC`에 EC2 인스턴스를 시작한다. 이 인스턴스에 모든 `DNS` 요청을 온프레미스 `DNS` 서버로 전달하는 사용자 지정 `DNS` 포워더를 배포한다. 이 EC2 인스턴스를 네임 서버로 사용하는 Amazon Route 53 프라이빗 호스팅 영역을 만든다.",
   "Amazon Route 53 Resolver 아웃바운드 엔드포인트를 만든다. 온프레미스 도메인에 대한 `DNS` 쿼리를 온프레미스 `DNS` 서버로 전달하도록 이 아웃바운드 엔드포인트를 구성한다.",
   "AWS 환경과 온프레미스 네트워크 사이에 AWS Direct Connect 연결 두 개를 설정한다. 이 두 연결을 포함하는 링크 집계 그룹(LAG)을 설정한다. `VPC` 확인자(resolver) 주소를 온프레미스 `DNS` 서버로 변경한다.",
   "온프레미스 도메인에 대한 Amazon Route 53 퍼블릭 호스팅 영역을 만든다. 온프레미스 도메인에 대한 `DNS` 요청을 Route 53 퍼블릭 호스팅 영역으로 전달하도록 네트워크 `ACL`을 구성한다."
  ]
 },
