 "soapt-q099": {
  "q": "어느 회사가 두 애플리케이션을 연결하려고 합니다. 한 애플리케이션은 호스트 이름이 hostl.onprem.private인 온프레미스 데이터 센터에서 실행되고, 다른 애플리케이션은 호스트 이름이 `hostl.awscloud.private`인 Amazon EC2 인스턴스에서 실행됩니다. 온프레미스 네트워크와 AWS 사이에는 AWS Site-to-Site `VPN` 연결이 구성되어 있습니다. 데이터 센터의 애플리케이션이 EC2 인스턴스의 애플리케이션에 연결을 시도하지만 `DNS` 확인이 실패합니다. CloudOps 엔지니어는 온프레미스와 AWS 리소스 간 `DNS` 확인을 구현해야 합니다. 온프레미스 애플리케이션이 EC2 인스턴스 호스트 이름을 확인할 수 있게 하는 솔루션은 무엇입니까?",
  "c": [
   "onprem.private 호스팅 영역에 대한 전달 규칙을 갖는 Amazon Route 53 인바운드 확인자(resolver) 엔드포인트를 설정한다. 이 확인자를 EC2 인스턴스의 `VPC`에 연결한다. 온프레미스 `DNS` 확인자가 onprem.private `DNS` 쿼리를 이 인바운드 확인자 엔드포인트로 전달하도록 구성한다.",
   "Amazon Route 53 인바운드 확인자 엔드포인트를 설정한다. 이 확인자를 EC2 인스턴스의 `VPC`에 연결한다. 온프레미스 `DNS` 확인자가 awscloud.private `DNS` 쿼리를 이 인바운드 확인자 엔드포인트로 전달하도록 구성한다.",
   "onprem.private 호스팅 영역에 대한 전달 규칙을 갖는 Amazon Route 53 아웃바운드 확인자 엔드포인트를 설정한다. 이 확인자를 EC2 인스턴스의 AWS 리전에 연결한다. 온프레미스 `DNS` 확인자가 onprem.private `DNS` 쿼리를 이 아웃바운드 확인자 엔드포인트로 전달하도록 구성한다.",
   "Amazon Route 53 아웃바운드 확인자 엔드포인트를 설정한다. 이 확인자를 EC2 인스턴스의 AWS 리전에 연결한다. 온프레미스 `DNS` 확인자가 awscloud.private `DNS` 쿼리를 이 아웃바운드 확인자 엔드포인트로 전달하도록 구성한다."
  ]
 },
