  "q": "CloudOps 엔지니어가 간단한 비프로덕션 웹페이지를 호스팅하도록 Amazon S3를 구성해야 합니다. CloudOps 엔지니어는 AWS Management Console에서 빈 S3 버킷을 만들었고, 이 S3 버킷에는 기본 구성이 적용되어 있습니다. 이 과정을 완료하려면 CloudOps 엔지니어는 어떤 조치의 조합을 취해야 합니까? (2개 선택)",
