 "soapt-q232": {
  "q": "어느 회사가 고객의 판매 데이터를 분석합니다. 고객이 회사의 Amazon S3 버킷 중 하나에 파일을 업로드하면, 객체 Amazon 리소스 이름(ARN)이 담긴 메시지가 Amazon Simple Queue Service(Amazon SQS) 큐에 게시됩니다. Amazon EC2 인스턴스에서 실행되는 애플리케이션이 이 큐를 폴링해 메시지를 처리하며, 처리 시간은 파일 크기에 따라 달라집니다. 고객들이 파일 처리 지연을 보고하고 있습니다. CloudOps 엔지니어는 첫 단계로 Amazon EC2 Auto Scaling을 구성하기로 했습니다. CloudOps 엔지니어는 기존 EC2 인스턴스를 기반으로 Amazon 머신 이미지(AMI)를 만들고, 그 AMI를 참조하는 시작 템플릿도 만들었습니다. 응답 시간을 개선하려면 CloudOps 엔지니어는 Auto Scaling 정책을 어떻게 구성해야 합니까?",
  "c": [
   "시작 템플릿에 여러 인스턴스 크기를 추가한다. `ApproximateNumberOfMessagesVisible` 지표를 기반으로 하는 Auto Scaling 정책을 만들어, 큐의 메시지 수에 따라 인스턴스 크기를 선택한다.",
   "지연된 메시지 수에 따라 인스턴스 수를 조정하도록 ApproximateNumberOfMessagesDelayed 지표를 기반으로 하는 Auto Scaling 정책을 만든다.",
   "Auto Scaling 그룹의 `ASGAverageCPUUtilization` 지표와 GroupPendingInstances 지표를 기반으로 사용자 지정 지표를 만든다. 애플리케이션이 이 지표를 계산해 1분에 한 번 Amazon CloudWatch에 게시하도록 수정한다. 이 지표를 기반으로 인스턴스 수를 조정하는 Auto Scaling 정책을 만든다.",
   "`ApproximateNumberOfMessagesVisible` 지표와 Auto Scaling 그룹의 `InService` 상태 인스턴스 수를 기반으로 사용자 지정 지표를 만든다. 애플리케이션이 이 지표를 계산해 1분에 한 번 Amazon CloudWatch에 게시하도록 수정한다. 이 지표를 기반으로 인스턴스 수를 조정하는 Auto Scaling 정책을 만든다."
  ]
 },
