   "Aurora 클러스터를 모니터링하도록 AWS Auto Scaling을 구성한다. 기존 Aurora 복제본의 평균 CPU 사용률을 기준으로 클러스터의 Aurora 복제본을 추가·제거하도록 AWS Auto Scaling을 구성한다."
