 "soapt-q384": {
  "q": "어느 회사에 `www.example.com`용 기존 퍼블릭 웹 애플리케이션이 있습니다. Application Load Balancer(ALB)는 `HTTP` `80` 리스너 하나로 구성되어 있습니다. CloudOps 엔지니어는 `www.example.com`으로 향하는 모든 웹 요청이 클라이언트와 `ALB` 사이에서 암호화되도록 해야 합니다. CloudOps 엔지니어는 이미 AWS Certificate Manager(ACM)에서 `www.example.com`용 퍼블릭 인증서를 요청하고 검증해 두었습니다. 기존 애플리케이션 사용자는 연결하는 엔드포인트를 변경하지 않아도 되어야 합니다. 이 요구 사항을 충족하려면 CloudOps 엔지니어는 추가로 어떤 단계를 취해야 합니까?",
  "c": [
   "포트 `443`에 `HTTPS`용 `ALB` 리스너를 추가로 만든다. 기본 작업을 모든 트래픽을 대상 그룹으로 전달하도록 설정한다. `www.example.com`용으로 만든 ACM 인증서를 기본 SSL 인증서로 지정한다.",
   "포트 `443`에 `HTTPS`용 `ALB` 리스너를 추가로 만든다. 기본 작업을 모든 트래픽을 대상 그룹으로 전달하도록 설정한다. `www.example.com`용으로 만든 ACM 인증서를 기본 SSL 인증서로 지정한다. 포트 `80`의 원래 `HTTP` 리스너를 삭제한다.",
   "`HTTP` 포트 `80` 리스너의 `ALB` 기본 규칙을 수정한다. 그 리스너에 www.example.com 호스트의 모든 트래픽을 대상 그룹으로 전달하는 규칙을 만든다. `www.example.com`용으로 만든 ACM 인증서를 기본 SSL 인증서로 지정한다.",
   "`HTTP` 포트 `80` 리스너의 `ALB` 기본 규칙을 포트 `443`의 `HTTPS`로 리디렉션하도록 수정한다. 포트 `443`에 `HTTPS` 리스너를 추가로 만든다. 기본 작업을 모든 트래픽을 대상 그룹으로 전달하도록 설정한다. `www.example.com`용으로 만든 ACM 인증서를 기본 SSL 인증서로 지정한다."
  ]
 },
